<script setup lang="ts">
import { computed, onBeforeUnmount, ref } from 'vue'
import { ChevronDown, ChevronRight, File, FolderOpen, PanelLeft, PanelRight, Plus, Search, X } from 'lucide-vue-next'
import PreviewPanelContent from './PreviewPanelContent.vue'
import PreviewSidebarGroup from './PreviewSidebarGroup.vue'
import SidebarManagerPreview from '../plugins/ui/SidebarManagerDialog.vue'
const files = [
  { id: 'design', name: '插件系统设计.md', title: '插件系统设计', tags: ['产品设计', 'Markart'], intro: '插件负责拓展功能，应用负责组织界面。让写作保持在中心，也让需要的工具随手可及。' },
  { id: 'writing', name: '写作流程.md', title: '写作流程', tags: ['写作', '工作流'], intro: '从一个想法开始，收集资料、组织结构，再逐步完成正文。工具在需要的时候出现。' },
  { id: 'index', name: '知识索引.md', title: '知识索引', tags: ['知识管理', 'Markart'], intro: '文件之间的链接构成可探索的关系。索引记录这些联系，图谱帮助我们看见它们。' },
  { id: 'plan', name: '项目计划.md', title: '项目计划', tags: ['产品设计', '工作流'], intro: '先验证交互，再明确接口边界。每个阶段都留下可运行、可观察、可调整的结果。' },
]

type Panel = 'files' | 'outline' | 'graph' | 'tags' | 'backlinks'
type Region = 'leftTop' | 'leftBottom' | 'rightTop' | 'rightBottom'
const regions: {id: Region; label:string}[] = [{id:'leftTop',label:'左侧上方'},{id:'leftBottom',label:'左侧下方'},{id:'rightTop',label:'右侧上方'},{id:'rightBottom',label:'右侧下方'}]
const titles: Record<Panel,string> = {files:'文件',outline:'大纲',graph:'图谱',tags:'标签',backlinks:'反向链接'}
const initialGroups = (): Record<Region,Panel[]> => ({leftTop:['files'],leftBottom:['outline'],rightTop:['graph','tags'],rightBottom:['backlinks']})
const groups = ref(initialGroups())
const managerOpen=ref(true)
function placePanel(id:string,target:string,before?:string){
 for(const region of regions){if(groups.value[region.id].includes(id as Panel))closePanel(region.id,id,true)}
 if(target==='library')return
 const key=target as Region,list=groups.value[key],index=before?list.indexOf(before as Panel):-1
 list.splice(index<0?list.length:index,0,id as Panel);active.value[key]=id as Panel
 if(target.startsWith('left'))leftOpen.value=true;else rightOpen.value=true
}
const active = ref<Record<Region,Panel>>({leftTop:'files',leftBottom:'outline',rightTop:'graph',rightBottom:'backlinks'})
const activeFile = ref('design'), openFiles = ref(['design','writing']), folderOpen = ref(true), search = ref('')
const leftOpen = ref(true), rightOpen = ref(true), rightWidth = ref(innerWidth < 850 ? 250 : 320)
const ratios = ref({left:.56,right:.56})
const panelTags = ref<Record<string,string>>({})
const file = computed(() => files.find(item => item.id === activeFile.value) || files[0])
const filteredFiles = computed(() => files.filter(item => item.name.toLowerCase().includes(search.value.toLowerCase())))
const tags = computed(() => [...new Set(files.flatMap(item => item.tags))].map(name => ({name,files:files.filter(item => item.tags.includes(name))})))
const available = computed(() => (Object.keys(titles) as Panel[]).filter(id => !Object.values(groups.value).flat().includes(id)))
function visibleRegions(side:'left'|'right') {
  const sameSide=regions.filter(item=>item.id.startsWith(side))
  const occupied=sameSide.filter(item=>groups.value[item.id].length)
  return occupied.length ? occupied : [sameSide[0]]
}
function regionRows(side:'left'|'right') {
  return visibleRegions(side).length === 1 ? 'minmax(0, 1fr)' : `minmax(0, ${ratios.value[side]}fr) 1px minmax(0, ${1-ratios.value[side]}fr)`
}
function openFile(id:string) { activeFile.value = id; if (!openFiles.value.includes(id)) openFiles.value.push(id) }
function closeFile(id:string) { openFiles.value = openFiles.value.filter(value => value !== id); if (activeFile.value === id) activeFile.value = openFiles.value.at(-1) || 'design' }
function closePanel(region:Region, panel:string, keep=false) { const list=groups.value[region]; const index=list.indexOf(panel as Panel); groups.value[region]=list.filter(id => id !== panel); if(active.value[region] === panel) active.value[region]=groups.value[region][Math.min(index,groups.value[region].length-1)]; if(!keep) delete panelTags.value[panel] }
function movePanel(source:Region,panel:string,target:string) { closePanel(source,panel,true); groups.value[target as Region].push(panel as Panel); active.value[target as Region]=panel as Panel }
function addPanel(region:Region,panel:string) { groups.value[region].push(panel as Panel); active.value[region]=panel as Panel }
function scrollArticle(index=0) { document.getElementById('preview-article')?.scrollTo({top:index*190,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'}) }
let stopResize: (()=>void) | undefined
function resize(event:PointerEvent, side:'left'|'right', vertical=false) {
  if(event.button !== 0) return
  event.preventDefault(); stopResize?.()
  const area=(event.currentTarget as HTMLElement).parentElement!, rect=area.getBoundingClientRect(), start=rightWidth.value, x=event.clientX
  const move=(next:PointerEvent)=> { if(vertical) ratios.value[side]=Math.max(.22,Math.min(.78,(next.clientY-rect.top)/rect.height)); else rightWidth.value=Math.max(220,Math.min(460,innerWidth-440,start+x-next.clientX)) }
  const stop=()=>{window.removeEventListener('pointermove',move);window.removeEventListener('pointerup',stop);window.removeEventListener('pointercancel',stop);window.removeEventListener('blur',stop);document.body.style.cursor='';document.body.style.userSelect='';stopResize=undefined}
  window.addEventListener('pointermove',move);window.addEventListener('pointerup',stop);window.addEventListener('pointercancel',stop);window.addEventListener('blur',stop);document.body.style.cursor=vertical?'row-resize':'col-resize';document.body.style.userSelect='none';stopResize=stop
}
onBeforeUnmount(()=>stopResize?.())
function reset() { groups.value=initialGroups();active.value={leftTop:'files',leftBottom:'outline',rightTop:'graph',rightBottom:'backlinks'};ratios.value={left:.56,right:.56};leftOpen.value=rightOpen.value=true;panelTags.value={} }
</script>
<template>
  <div class="preview-page">
    <div class="app-shell dock-preview" :style="{'--right-width':`${rightWidth}px`}">
    <SidebarManagerPreview :open="managerOpen" :groups="groups" :regions="regions" :titles="titles" @close="managerOpen=false" @place="placePanel"/>

      <template v-for="side in ['left','center','right'] as const" :key="side">
        <main v-if="side === 'center'" class="preview-center">
          <header class="preview-editorbar"><button v-if="!leftOpen" class="icon-button" aria-label="展开左侧栏" @click="leftOpen=true"><PanelLeft :size="15"/></button><div class="preview-file-tabs"><div v-for="id in openFiles" :key="id" class="preview-file-tab" :class="{active:activeFile === id}"><button @click="openFile(id)"><File :size="13"/><span>{{files.find(item=>item.id===id)?.name}}</span></button><button class="preview-tab-close" aria-label="关闭标签页" @click="closeFile(id)"><X :size="11"/></button></div></div><button class="icon-button" aria-label="打开项目计划" @click="openFile('plan')"><Plus :size="15"/></button><span class="preview-bar-separator"/><button class="icon-button" aria-label="展开或收起右侧栏" :aria-expanded="rightOpen" @click="rightOpen=!rightOpen"><PanelRight :size="15"/></button></header>
          <article id="preview-article" class="preview-article"><div class="preview-prose"><h1>{{file.title}}</h1><p class="preview-intro">{{file.intro}}</p><h2>界面与内容</h2><p>左右侧栏各分上下两个区域。每个区域可以放入多个面板，点击名称切换，同一时间显示一个面板。</p><blockquote>四个位置，自由组织，内容始终在中心。</blockquote><h2>面板的工作方式</h2><p>通过“管理侧栏”，将面板移到其他区域。切换和移动都会保留面板状态。</p><ul><li>点击区域顶部的名称切换面板。</li><li>在菜单中选择面板的新位置。</li><li>拖动侧栏中间的分割线调整上下高度。</li></ul><h2>下一步</h2><p>确认交互后，再将四个区域接入统一的面板 API。</p></div></article><footer class="preview-status"><span>交互预览 · 示例文件</span></footer>
        </main>
        <aside v-else-if="side === 'left' ? leftOpen : rightOpen" :class="['preview-side',`preview-${side}`]">
          <header class="preview-windowbar"><template v-if="side === 'left'"><span class="preview-traffic"><i/><i/><i/></span><button class="icon-button" aria-label="收起左侧栏" @click="leftOpen=false"><PanelLeft :size="15"/></button><FolderOpen :size="15" class="preview-muted"/></template><span v-else class="preview-side-label">面板</span></header>
          <div v-if="side === 'right'" class="preview-right-resizer" role="separator" aria-label="调整右侧栏宽度" aria-orientation="vertical" tabindex="0" @pointerdown="resize($event,side)" @keydown.left.prevent="rightWidth=Math.min(460,rightWidth+10)" @keydown.right.prevent="rightWidth=Math.max(220,rightWidth-10)"/>
          <div class="preview-region-stack" :style="{gridTemplateRows:regionRows(side)}">
            <template v-for="(region,index) in visibleRegions(side)" :key="region.id">
              <div v-if="index" class="preview-height-resizer" role="separator" :aria-label="`调整${side==='left'?'左':'右'}侧上下区域高度`" aria-orientation="horizontal" tabindex="0" @pointerdown="resize($event,side,true)" @keydown.up.prevent="ratios[side]=Math.max(.22,ratios[side]-.03)" @keydown.down.prevent="ratios[side]=Math.min(.78,ratios[side]+.03)"/>
              <PreviewSidebarGroup :id="region.id" :label="region.label" :panels="groups[region.id]" :active="active[region.id]" :titles="titles" :regions="regions" :available="available" @select="active[region.id]=$event as Panel" @move="(panel,target)=>movePanel(region.id,panel,target)" @close="closePanel(region.id,$event)" @add="addPanel(region.id,$event)">
                <template v-if="active[region.id] === 'files'"><label class="preview-file-search"><Search :size="13"/><input v-model="search" placeholder="搜索文件" aria-label="搜索文件"/></label><button class="preview-root" @click="folderOpen=!folderOpen"><ChevronDown v-if="folderOpen" :size="14"/><ChevronRight v-else :size="14"/><FolderOpen :size="16"/><span>Markart</span></button><div v-if="folderOpen" class="preview-file-list"><button v-for="item in filteredFiles" :key="item.id" :class="{selected:activeFile===item.id}" @click="openFile(item.id)"><File :size="15"/><span>{{item.name}}</span></button><p v-if="!filteredFiles.length" class="preview-empty-small">没有匹配的文件</p></div></template>
                <div v-else class="preview-region-panel"><PreviewPanelContent :id="active[region.id]" :file="file" :files="files" :tags="tags" v-model:selected-tag="panelTags[active[region.id]]" @open-file="openFile" @scroll-heading="scrollArticle"/></div>
              </PreviewSidebarGroup>
            </template>
          </div>
        </aside>
      </template>
    </div><div class="preview-note"><span>左右侧栏预览</span><span>切换面板、移动位置或调整上下高度。</span><button @click="managerOpen=true">管理侧栏</button><button @click="reset">恢复布局</button></div>
  </div>
</template>
